package io.github.capozziv.digitalbanking.transfers.adapters.web

import io.swagger.v3.oas.models.Components
import io.swagger.v3.oas.models.OpenAPI
import io.swagger.v3.oas.models.info.Info
import io.swagger.v3.oas.models.security.SecurityScheme
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration

/**
 * OpenAPI contract of the transfers API, generated by springdoc from the controllers (`/v3/api-docs`).
 * The per-operation responses are annotated on the controllers, with status and description only. What every
 * operation shares comes from the libraries: 401, 403, 500 and the Problem Details content of every error response
 * (`:libs:security`), and the `X-Correlation-Id` header (`:libs:observabilidade`).
 */
@Configuration
class OpenApiConfiguration {
    @Bean
    fun transfersOpenApi(): OpenAPI =
        OpenAPI()
            .info(
                Info()
                    .title("transfers")
                    .version("v1")
                    .description(DESCRIPTION),
            ).components(
                Components().addSecuritySchemes(
                    BEARER_AUTH,
                    SecurityScheme()
                        .type(SecurityScheme.Type.HTTP)
                        .scheme("bearer")
                        .bearerFormat("JWT")
                        .description("Access token of a customer or of an admin (group `admin`)."),
                ),
            )

    companion object {
        /** Name of the security scheme every operation requires. */
        const val BEARER_AUTH = "bearerAuth"

        private val DESCRIPTION =
            """
            Transfers between accounts of the simulated digital bank, run as a saga over the accounts API.

            - Amounts are whole cents (integers); `amount` > 0.
            - A transfer is `PENDING` while the saga runs, then `COMPLETED`, `COMPENSATED` (the debit was given back)
              or `FAILED` (refused by accounts; `failureReason` says why).
            - Errors are Problem Details (RFC 9457, `application/problem+json`). Errors of this API have a relative
              `type` `/problems/<slug>`; `400 /problems/validation-error` lists the invalid fields in `errors`.
            - Errors raised by the framework itself (404 unknown route, 405 method not allowed, 415 unsupported
              media type, ...) are Problem Details without a `type` member, which RFC 9457 defines as `about:blank`.
            - Every operation needs `Authorization: Bearer <JWT>` of a customer or of an admin (`bearerAuth`). A
              customer only transfers from, and only sees, its own accounts and transfers; someone else's is answered
              with 404, as if it did not exist. An admin may do everything.
            - Before a transfer is created, the customer that owns the source account is checked with the customer
              service, every time: not registered or blocked is 422, customer unavailable is 503.
            - `X-Correlation-Id` is accepted on every request (generated when absent or invalid), forwarded to accounts
              and customer, and returned on every response.
            """.trimIndent()
    }
}

/** Texts shared by the OpenAPI annotations of the controllers. */
internal object ApiDocs {
    const val IDEMPOTENCY_KEY =
        "Required, 1 to 255 characters, not blank (a UUID is recommended). Scope: the whole service. Missing: " +
            "400 /problems/missing-idempotency-key, checked before the body, so a request without the key is " +
            "reported as missing even when its body is invalid."
}
